test("un cupón de 10% baja 200 a 180", () => {
	// Arrange: preparar la situación
	const cart = new Cart([{ price: 200 }]);
	// Act: hacer la única cosa que se prueba
	const total = cart.totalWith("TEN");
	// Assert: comparar con lo esperado
	expect(total).toBe(180);
});

const cart: string[] = [];          // compartido por todas las pruebas

test("adds an item", () => {
	cart.push("book");
	expect(cart.length).toBe(1);
});
test("adds a second item", () => {
	cart.push("pen");
	expect(cart.length).toBe(2);   // solo pasa si la primera prueba corrió antes
});

